INSERT INTO `ownerfiles` VALUES ('4', 'Dengue.txt', 'Dengue fever is a mosquito-borne tropical disease caused by the dengue virus.Symptoms typically begin three to fourteen days after infection.[2] This may include a high fever, headache, vomiting, muscle and joint pains, and a characteristic skin rash.Recovery generally takes two to seven days.In a small proportion of cases, the disease develops into the life-threatening dengue hemorrhagic fever, resulting in bleeding, low levels of blood platelets and blood plasma leakage, or into dengue shock syndrome, where dangerously low blood pressure occurs.', '[B@d7b7d9', 'sl19x0vf0k3q3p2k', '0', '28/10/2017   14:27:48', 'Kiran');
INSERT INTO `ownerfiles` VALUES ('7', 'Cancer.txt', 'Cancer is a group of diseases involving abnormal cell growth with the potential to invade or spread to other parts of the body. These contrast with benign tumors, which do not spread to other parts of the body. Possible signs and symptoms of cancer include a lump, abnormal bleeding, prolonged cough, unexplained weight loss, and a change in bowel movements.While these symptoms may indicate cancer, they may have other causes.Over 100 types of cancers affect humans.', '[B@11415c8', 'qi89t4ul3u0o4o8i', '0', '28/10/2017   14:52:01', 'Manjunath');
